// LaunchResolver.sol's last three steps: the extension's binding (_extension, _custom, _preset), the start
// (LaunchPricing.checkStart: the table's form, the scheduled start, the pad's FDV window and B21 at one price) and
// the curve against the pad's list (_curve).

function custom(p: Params, t: Terms, x: Ctx): void {
  const e = p.extension;
  let [qg, ag] = [e.quoteGas, e.afterGas];
  if (
    size(e.params) !== 0 ||
    qg === BANKR_V4_EXT_QUOTE_GAS ||
    ag === BANKR_V4_EXT_AFTER_GAS
  ) {
    revert("AmbiguousExtension");
  }
  if (qg === 0) qg = BANKR_V4_EXT_QUOTE_GAS;
  if (ag === 0 && !e.quoteOnly) ag = BANKR_V4_EXT_AFTER_GAS;
  let payee = e.payee;
  if (isZero(payee)) {
    if (p.feeRecipients.length > 1) revert("ExtensionPayeeUnnamed");
    payee = p.feeRecipients[0]?.recipient ?? x.launcher;
  }
  t.pool.payee = payee;
  const code = x.s.extensionCode;
  hold(
    B.bankrV4ExtensionBound({
      code: {
        exists: code?.exists ?? false,
        startsEf: code?.startsEf ?? false,
        atPinnedHash: code?.codehash.toLowerCase() === e.codehash.toLowerCase(),
      },
      hasPayee: !isZero(payee),
      quoteOnly: e.quoteOnly,
      quoteGas: qg,
      afterGas: ag,
    }),
  );
  const declared = Math.max(e.maxBuyPips, e.maxSellPips);
  t.extMaxPips = Number(under(x, K.extMaxPips, declared));
  Object.assign(t.pool, {
    ext: e.ext,
    quoteGas: qg,
    afterGas: ag,
    codehash: e.codehash,
    maxBuyPips: e.maxBuyPips,
    maxSellPips: e.maxSellPips,
    quoteOnly: e.quoteOnly,
    sunsetSecs: e.sunsetSecs,
  });
}

function preset(p: Params, t: Terms, x: Ctx): void {
  const e = p.extension;
  if (
    !isZero(e.ext) ||
    e.quoteOnly ||
    (e.maxBuyPips | e.maxSellPips | e.sunsetSecs | e.quoteGas | e.afterGas) !==
      0
  ) {
    revert("AmbiguousExtension");
  }
  const r = x.s.preset?.record;
  const at = x.pad.presetIds.indexOf(e.id);
  const l = at < 0 ? undefined : x.pad.presetLimits[at];
  if (!r?.active || !l?.allowed) return revert("PresetOff", e.id);
  const same = (a: Hex, b: Hex) => a.toLowerCase() === b.toLowerCase();
  if (
    !same(x.s.preset!.deployerCodeHashNow, r.deployerCodeHash) ||
    (BigInt(e.codehash) !== 0n && !same(e.codehash, r.creationCodeHash))
  ) {
    revert("PresetCodeChanged");
  }
  t.presetId = e.id;
  [t.presetCodeHash, t.presetDeployer] = [r.creationCodeHash, r.deployer];
  t.presetDeployerCodeHash = r.deployerCodeHash;
  t.presetSelfPayee = r.selfPayee;
  t.extMaxPips = Number(under(x, K.extMaxPips, 0));
  t.presetSite = B.encodeBankrV4PresetSite({
    maxPips: t.extMaxPips,
    minWindowSecs: Math.max(t.pool.buy.decaySecs, t.pool.sell.decaySecs),
    maxWindowSecs: l.maxWindowSecs,
    minBrakeTicks: l.minBrakeTicks,
    minAnchorTau: l.minAnchorTau,
    maxDustFloor: B.bankrV4PresetDustCeiling(x.s.quote.terms.compoundFloor),
  });
}

export function extension(p: Params, t: Terms, x: Ctx): void {
  const e = p.extension;
  if (e.id === 0 && isZero(e.ext)) return unset(x, O.OPT_FEE_CEILING);
  const o = x.s.protocol;
  [t.pool.bankrNum, t.pool.bankrDen] = [o.extBankrNum, o.extBankrDen];
  t.pool.feeCeilingPips = Number(
    pick(x, K.feeCeilingPips, O.OPT_FEE_CEILING, x.o.feeCeilingPips),
  );
  hold(
    B.bankrV4BuybackFeeBound({
      buyback: t.pool.buyback,
      buySteadyPips: 0,
      feeCeilingPips: t.pool.feeCeilingPips,
    }),
  );
  t.pool.ownerSwitch = (x.flags & F.extOwnerSwitch) !== 0n;
  let charges = true;
  if (e.id !== 0) {
    flag(x, F.extPresets);
    preset(p, t, x);
  } else {
    flag(x, e.quoteOnly ? F.extQuoteOnly : F.extCallsOut);
    custom(p, t, x);
    charges = (e.maxBuyPips | e.maxSellPips) !== 0;
  }
  if (charges) flag(x, F.extOwnerSwitch);
  if (!x.s.extensionAllowed) revert("ExtensionNotAllowlisted");
}

/** LaunchPricing._price: a feed behind the sequencer gate, or the launch's own attestation. Fail-closed. */
function price(p: Params, x: Ctx): bigint {
  const { terms: q, feedPriceUsdE18 } = x.s.quote;
  if (q.mode === BANKR_V4_PRICING_MODE.chainlink) {
    return feedPriceUsdE18 ?? revert("StartPriceUnavailable");
  }
  if (q.mode !== BANKR_V4_PRICING_MODE.signed || isZero(x.s.priceSigner)) {
    revert("StartPriceUnavailable");
  }
  const a = p.priceAttestation;
  const signer = x.s.attestationSigner;
  if (
    a.priceUsdE18 === 0n ||
    a.observedAt > x.s.now ||
    a.expiresAt < x.s.now ||
    x.s.now - a.observedAt > BigInt(q.maxPriceAge) ||
    !signer ||
    !isAddressEqual(signer, x.s.priceSigner)
  ) {
    revert("InvalidPriceAttestation");
  }
  return a.priceUsdE18;
}

/** LaunchPricing.checkStart: the table's form, the scheduled start, and on a listed quote the FDV window and B21. */
export function start(p: Params, t: Terms, x: Ctx): void {
  if (
    p.curveId > 2n &&
    !checkBankrV4CurveFormat(p.curveId, p.expectedStartTick)
  ) {
    revert("InvalidCurve");
  }
  if (t.startTime !== 0n) {
    if (t.startTime <= x.s.now) revert("StartPassed");
    if (t.startTime - x.s.now > range(x, K.startDelaySecs).max) {
      revert("StartTooFar");
    }
  }
  const q = x.s.quote.terms;
  if (!q.allowed) return;
  const px = price(p, x);
  const { lowest, highest } = bankrV4StartWindow({
    fdvUsd: range(x, K.startFdvUsd),
    decimals: q.decimals,
    priceUsdE18: px,
    supply: t.totalSupply,
  });
  if (p.expectedStartTick < lowest || p.expectedStartTick > highest) {
    revert("StartTickOutOfBounds", lowest, highest);
  }
  hold(
    B.bankrV4CompoundCapUsdFloorBound({
      compoundCap: t.pool.compoundCap,
      decimals: q.decimals,
      priceUsdE18: px,
    }),
  );
  hold(
    B.bankrV4QuoteAmountUsdBound({
      amount:
        t.pool.compoundCap > t.quoteActivation
          ? t.pool.compoundCap
          : t.quoteActivation,
      decimals: q.decimals,
      priceUsdE18: px,
      maxCompoundUsd: x.s.guards.maxCompoundUsd,
    }),
  );
}

export function curve(key: bigint, t: Terms, x: Ctx): void {
  if (!x.s.curveAllowed && (key < 3n || !x.s.anyTableAllowed)) {
    revert("CurveNotAllowedByLaunchpad");
  }
  if (key <= 2n) {
    t.curve.builtIn = true;
    return;
  }
  const dflt = (knob: number) => Number(range(x, knob).dflt);
  t.curve.minDepthDiv = dflt(K.curveMinDepthDiv);
  t.curve.maxDensity = dflt(K.curveMaxDensity);
  t.curve.placeTicks = dflt(K.curvePlaceTicks);
  t.curve.placeBps = dflt(K.curvePlaceBps);
  t.curve.dustPpm = dflt(K.curveDustPpm);
  // B17: only where the pool may buy its own token, inside its compound half width (the pad's default with none).
  const buys =
    x.lp || t.pool.buyback || t.pool.afterGas !== 0 || t.presetId !== 0;
  if (!buys) return;
  const half = x.lp ? t.pool.bandHalfWidth : dflt(K.bandHalfWidth);
  t.curve.nearStep = x.s.guards.curveNearStep;
  t.curve.nearTicks = half * BANKR_V4_TICK_SPACING;
}
